package cl.acis.catalogos.exception; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.stream.*;
@RestControllerAdvice public class ApiExceptionHandler{record Error(LocalDateTime timestamp,int status,String error,String mensaje){} ResponseEntity<Error> e(HttpStatus s,String m){return ResponseEntity.status(s).body(new Error(LocalDateTime.now(),s.value(),s.getReasonPhrase(),m));}@ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Error> v(MethodArgumentNotValidException x){return e(HttpStatus.BAD_REQUEST,x.getBindingResult().getFieldErrors().stream().map(a->a.getDefaultMessage()).collect(Collectors.joining("; ")));}@ExceptionHandler(NoAutorizadoException.class) ResponseEntity<Error> n(NoAutorizadoException x){return e(HttpStatus.UNAUTHORIZED,x.getMessage());}@ExceptionHandler(ProhibidoException.class) ResponseEntity<Error> p(ProhibidoException x){return e(HttpStatus.FORBIDDEN,x.getMessage());}@ExceptionHandler(RecursoNoEncontradoException.class) ResponseEntity<Error> f(RecursoNoEncontradoException x){return e(HttpStatus.NOT_FOUND,x.getMessage());}@ExceptionHandler(ReglaNegocioException.class) ResponseEntity<Error> r(ReglaNegocioException x){return e(HttpStatus.BAD_REQUEST,x.getMessage());}}
